"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["4672"],{20921(e){e.exports=JSON.parse('{"id":"FIN-511","slug":"annuity-due","term":"Annuity Due","also_known_as":[],"difficulty":"Intermediate","definition":"An annuity due is a series of equal payments made at the beginning of each period, such as rent paid at the start of each month.","explanation":["The only difference between an annuity due and an ordinary annuity is timing. In an annuity due, the first payment happens immediately, and each later payment comes at the start of its period rather than the end.","Common examples include rent, insurance premiums, many lease payments and subscriptions, which are usually paid in advance.","Because each payment arrives one period earlier, an annuity due is worth more than an equivalent ordinary annuity. Suppose you will receive 1,000 at the start of each year for three years, and money earns 5%. The value today is about 2,859, compared with about 2,723 if the same payments came at the end of each year. The annuity due is worth exactly 5% more, because each payment has one extra period to earn interest.","The same idea applies to saving. If you invest a fixed amount at the start of each month rather than the end, your savings will grow slightly larger over time, because every deposit earns interest for one extra month."],"note":"","total":1500,"prev":{"slug":"annuity","term":"Annuity"},"next":{"slug":"anti-dilution-protection","term":"Anti-Dilution Protection"}}')}}]);